import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { useAppContext } from "../context/AppContext";

export function useThreeJS(containerRef) {
  const { state } = useAppContext();
  const sceneRef = useRef(null);
  const rendererRef = useRef(null);
  const cameraRef = useRef(null);
  const animationIdRef = useRef(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Initialize Three.js scene
  useEffect(() => {
    if (!containerRef.current || isInitialized) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x111177); // Dark blue for debugging
    sceneRef.current = scene;

    // Camera setup
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(
      state.camera.position.x,
      state.camera.position.y,
      state.camera.position.z
    );
    camera.lookAt(0, 0, 0); // Add this line
    cameraRef.current = camera;

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false, // Force opaque canvas
    });
    renderer.setSize(window.innerWidth, window.innerHeight);

    // Force a very obvious clear color - bright magenta
    renderer.setClearColor(0xff00ff, 1); // Bright magenta, fully opaque

    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    rendererRef.current = renderer;

    console.log("useThreeJS: Renderer DOM element:", renderer.domElement); // Log the canvas
    console.log("useThreeJS: Canvas width:", renderer.domElement.width);
    console.log("useThreeJS: Canvas height:", renderer.domElement.height);
    console.log("useThreeJS: WebGL context:", renderer.getContext());
    console.log(
      "useThreeJS: WebGL context lost?",
      renderer.getContext().isContextLost()
    );

    // Explicitly style the canvas for debugging
    renderer.domElement.style.position = "absolute";
    renderer.domElement.style.top = "0px";
    renderer.domElement.style.left = "0px";
    renderer.domElement.style.zIndex = "10";
    renderer.domElement.style.border = "5px solid lime"; // Bright green border
    renderer.domElement.style.opacity = "1"; // Ensure it's not transparent via CSS
    renderer.domElement.style.visibility = "visible"; // Ensure it's visible

    // Add renderer to DOM
    containerRef.current.appendChild(renderer.domElement);

    // DEBUGGING: Try to draw directly to canvas with 2D context
    try {
      const canvas2d = document.createElement("canvas");
      canvas2d.width = window.innerWidth;
      canvas2d.height = window.innerHeight;
      canvas2d.style.position = "absolute";
      canvas2d.style.top = "0px";
      canvas2d.style.left = "0px";
      canvas2d.style.zIndex = "5";
      canvas2d.style.border = "5px solid red";
      canvas2d.style.pointerEvents = "none";

      const ctx = canvas2d.getContext("2d");
      ctx.fillStyle = "yellow";
      ctx.fillRect(0, 0, canvas2d.width, canvas2d.height);
      ctx.fillStyle = "black";
      ctx.font = "48px Arial";
      ctx.fillText("2D CANVAS TEST", 100, 100);

      containerRef.current.appendChild(canvas2d);
      console.log("Added 2D canvas test");
    } catch (error) {
      console.error("2D canvas test failed:", error);
    }

    // Add a tiny invisible point to force rendering (DEBUGGING)
    const pointGeometry = new THREE.BufferGeometry();
    const vertices = new Float32Array([0, 0, 0]); // Single point at origin
    pointGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(vertices, 3)
    );
    const pointMaterial = new THREE.PointsMaterial({
      color: 0x000000,
      size: 0.001, // Extremely small
      transparent: true,
      opacity: 0.01, // Nearly invisible
    });
    const point = new THREE.Points(pointGeometry, pointMaterial);
    scene.add(point);

    // Lighting setup (TEMPORARILY COMMENTED OUT)
    // const ambientLight = new THREE.AmbientLight(0x404040, 0.4);
    // scene.add(ambientLight);
    //
    // const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    // directionalLight.position.set(5, 3, 5);
    // directionalLight.castShadow = true;
    // directionalLight.shadow.mapSize.width = 2048;
    // directionalLight.shadow.mapSize.height = 2048;
    // scene.add(directionalLight);

    // Create Earth geometry (TEMPORARILY COMMENTED OUT)
    // const earthGeometry = new THREE.SphereGeometry(1, 64, 64);
    // Earth material (TEMPORARILY SIMPLIFIED)
    // const earthMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00 }); // Bright green
    // Create Earth mesh (TEMPORARILY COMMENTED OUT)
    // const earth = new THREE.Mesh(earthGeometry, earthMaterial);
    // scene.add(earth);
    // earthRef.current = earth;

    // Handle window resize
    const handleResize = () => {
      if (cameraRef.current && rendererRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(window.innerWidth, window.innerHeight);
      }
    };

    window.addEventListener("resize", handleResize);
    setIsInitialized(true);

    // Cleanup function
    return () => {
      window.removeEventListener("resize", handleResize);
      if (animationIdRef.current) {
        cancelAnimationFrame(animationIdRef.current);
      }
      if (containerRef.current && rendererRef.current) {
        containerRef.current.removeChild(rendererRef.current.domElement);
      }
      if (rendererRef.current) {
        rendererRef.current.dispose();
      }
    };
  }, [containerRef, isInitialized]);

  // Animation loop
  useEffect(() => {
    if (!isInitialized || !state.animation.isPlaying) {
      if (!isInitialized)
        console.log("useThreeJS: Animation loop waiting for initialization...");
      if (isInitialized && !state.animation.isPlaying)
        console.log(
          "useThreeJS: Animation loop paused (state.animation.isPlaying is false)."
        );
      return;
    }

    console.log("useThreeJS: Starting animation loop.");

    const animate = () => {
      animationIdRef.current = requestAnimationFrame(animate); // Request next frame first

      if (state.camera.autoRotate) {
        sceneRef.current.rotation.y += state.camera.rotationSpeed;
      }

      if (
        rendererRef.current &&
        sceneRef.current &&
        cameraRef.current
        // earthRef.current // Earth is removed, so no need to check
      ) {
        // Add this line to ensure camera always looks at the origin
        cameraRef.current.lookAt(0, 0, 0);

        // Explicitly clear the renderer's buffers
        rendererRef.current.clear();

        // More detailed render debugging
        console.log("useThreeJS - About to render:");
        console.log("  Scene background:", sceneRef.current.background);
        console.log(
          "  Scene children count:",
          sceneRef.current.children.length
        );
        console.log("  Camera position:", cameraRef.current.position);
        console.log(
          "  Camera target:",
          cameraRef.current.getWorldDirection(new THREE.Vector3())
        );
        console.log("  Renderer info:", rendererRef.current.info);

        // Try to force render with explicit parameters
        rendererRef.current.render(sceneRef.current, cameraRef.current);

        console.log("useThreeJS - Render completed");

        // Log properties before rendering
        console.log("useThreeJS - Animate:", {
          timestamp: performance.now(),
          cameraPos: cameraRef.current.position.toArray(),
          cameraZoom: cameraRef.current.zoom,
          // earthVisible: earthRef.current.visible, // Earth is removed
          // earthPos: earthRef.current.position.toArray(), // Earth is removed
          // earthScale: earthRef.current.scale.toArray(), // Earth is removed
          rendererWidth: rendererRef.current.domElement.width,
          rendererHeight: rendererRef.current.domElement.height,
        });
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      } else {
        console.log(
          "useThreeJS - Animate: Renderer, scene, camera or earth ref is not current."
        );
        if (!rendererRef.current)
          console.log("useThreeJS - Animate: rendererRef is null");
        if (!sceneRef.current)
          console.log("useThreeJS - Animate: sceneRef is null");
        if (!cameraRef.current)
          console.log("useThreeJS - Animate: cameraRef is null");
        // if (!earthRef.current) // Earth is removed
        //   console.log("useThreeJS - Animate: earthRef is null");
      }
    };

    animate();

    return () => {
      console.log("useThreeJS: Cleaning up animation loop.");
      if (animationIdRef.current) {
        cancelAnimationFrame(animationIdRef.current);
      }
    };
  }, [
    isInitialized,
    state.animation.isPlaying,
    state.camera.autoRotate,
    state.camera.rotationSpeed,
  ]);

  // Update camera position when state changes
  useEffect(() => {
    if (cameraRef.current) {
      cameraRef.current.position.set(
        state.camera.position.x,
        state.camera.position.y,
        state.camera.position.z
      );
    }
  }, [state.camera.position]);

  // Update camera zoom
  useEffect(() => {
    if (cameraRef.current) {
      cameraRef.current.zoom = state.camera.zoom;
      cameraRef.current.updateProjectionMatrix();
    }
  }, [state.camera.zoom]);

  // Update Earth visibility (TEMPORARILY COMMENTED OUT)
  // useEffect(() => {
  //   if (earthRef.current) {
  //     earthRef.current.visible = state.earth.visible;
  //   }
  // }, [state.earth.visible]);

  // Update wireframe mode (TEMPORARILY COMMENTED OUT)
  // useEffect(() => {
  //   if (earthRef.current && earthRef.current.material.wireframe !== undefined) {
  //     earthRef.current.material.wireframe = state.earth.wireframe;
  //   }
  // }, [state.earth.wireframe]);

  return {
    scene: sceneRef.current,
    renderer: rendererRef.current,
    camera: cameraRef.current,
    // earth: earthRef.current, // Earth is removed
    isInitialized,
  };
}
